update pages set contenu = '{"gabarit":"fiche","chapeau":"Depuis mai 2024, Migen assure le maintien d''un deuxième centre logistique AMAZON : le site ETZ 2, à Metz. Le dispositif éprouvé sur ORY 4, à Paris, y a été transposé.","fiche":[],"contexte":"**Ouvrir un deuxième site avec un prestataire qui découvre le métier, c''est repartir de zéro.** Le temps d''apprentissage se paie en arrêts.\nCe que le nouveau site imposait :\n**La même exigence de continuité** : Le centre fonctionne sans interruption, comme celui de Paris.\n**Des créneaux courts** : Les opérations doivent tenir dans quelques heures.\n**Une coordination à reconstruire** : Les équipes locales ne sont pas celles d''ORY 4.\n**Aucune marge d''apprentissage** : Le préventif démarre au rythme du site, pas au rythme du prestataire.","intervention":"**Un mode opératoire transposé** : La méthode appliquée sur ORY 4 depuis 2022 est reprise sur ETZ 2 dès mai 2024, plutôt que réinventée.\n**Une équipe dédiée au site** : 10 techniciens polyvalents mobilisés ensemble, pour traiter simultanément un grand nombre d''interventions préventives.\n**Un rythme mensuel** : Une semaine d''intervention par mois sur le site de Metz.\n**Une préparation côté client** : Les équipes AMAZON organisent les opérations en amont et assurent la disponibilité des pièces de rechange.\n**Une exécution complète** : Migen prend en charge l''exécution, le contrôle et les tests en série des opérations.","resultats":[]}'::jsonb where path = '/preuves/amazon-nouveau-site/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"AMAZON"},{"libelle":"Site","valeur":"Centre logistique ETZ 2, Metz"},{"libelle":"Période","valeur":"Depuis mai 2024, mission en cours"},{"libelle":"Effectif Migen","valeur":"10 techniciens polyvalents"},{"libelle":"Durée d''intervention","valeur":"8 heures"},{"libelle":"Fréquence","valeur":"1 semaine par mois"},{"libelle":"Nature des travaux","valeur":"Maintenance préventive, contrôle, tests en série"},{"libelle":"Site de référence","valeur":"ORY 4, Paris, couvert depuis 2022"}]'::jsonb) where path = '/preuves/amazon-nouveau-site/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Un deuxième site confié","libelle":"ETZ 2 rejoint ORY 4. AMAZON travaille désormais avec Migen sur deux centres logistiques."},{"valeur":"Une opération maîtrisée","libelle":"L''organisation et l''entraînement des équipes, prestataires comme clientes, ont rendu maîtrisée une opération délicate."},{"valeur":"Un risque de défaillance réduit","libelle":"La continuité opérationnelle du site est tenue, créneau après créneau."}]'::jsonb) where path = '/preuves/amazon-nouveau-site/';
